def comps(g, skip):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] in skip or (i,j) in seen: continue
            col=g[i][j]; st=[(i,j)]; seen.add((i,j)); cells=[]
            while st:
                r,c=st.pop(); cells.append((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<H and 0<=nc<W and g[nr][nc]==col and (nr,nc) not in seen:
                        seen.add((nr,nc)); st.append((nr,nc))
            out.append((col,len(cells)))
    return out
